func (f *fleet) InspectVolumeInitialization(ctx context.Context, pins VolumeInitializationPins) (VolumeInitializationProof, error) {
	if pins.InstanceID == "" || pins.HostCreateKey == "" || pins.VolumeID == "" || pins.AttachmentID == "" ||
		pins.DatabaseID == "" || pins.PartitionID == "" || pins.AttachmentETag == "" || !validDevicePath(pins.Device) ||
		pins.FileSystemUUID == "" || pins.FileSystemType != "ext4" && pins.FileSystemType != "xfs" {
		return VolumeInitializationProof{}, errors.New("volume initialization pins are incomplete")
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, pins.DatabaseID, pins.PartitionID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	defer release()
	instances, err := f.Observe(ctx)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	var selected *Instance
	for i := range instances {
		if instances[i].ID == pins.InstanceID {
			selected = &instances[i]
			break
		}
	}
	if selected == nil || selected.CreateKey != pins.HostCreateKey || selected.State != "RUNNING" ||
		selected.BootDescriptorSHA256 == "" {
		return VolumeInitializationProof{}, fmt.Errorf("%w: signed host is not an owned running instance", ErrForeignResource)
	}
	matched := false
	for _, attachment := range selected.Attachments {
		if attachment.ID == pins.AttachmentID && attachment.VolumeID == pins.VolumeID &&
			attachment.InstanceID == pins.InstanceID && attachment.ETag == pins.AttachmentETag &&
			attachment.Device == pins.Device && attachment.State == "ATTACHED" &&
			!attachment.IsReadOnly && !attachment.IsShareable && attachment.IsPvEncryptionInTransitEnabled {
			matched = true
		}
	}
	if !matched {
		return VolumeInitializationProof{}, fmt.Errorf("%w: signed attachment is not current on the owned instance", ErrForeignResource)
	}
	volume, err := f.ownedVolume(ctx, pins.VolumeID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	if volume.LifecycleState != "AVAILABLE" || volume.CompartmentID != f.config.CompartmentID ||
		volume.AvailabilityDomain != f.config.AvailabilityDomain {
		return VolumeInitializationProof{}, fmt.Errorf("%w: retained volume is not the available regional resource", ErrForeignResource)
	}
	attachments, err := f.findVolumeAttachments(ctx, pins.VolumeID)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	if len(attachments) != 1 || attachments[0].ID != pins.AttachmentID || attachments[0].InstanceID != pins.InstanceID {
		// A reattached volume keeps the DETACHED attachment of its fenced
		// host. Only a recorded mount-existing permit for exactly this
		// attachment admits that history, and it never grants a format.
		mountOnly, err := f.mountExistingPermitted(ctx, pins, attachments)
		if err != nil {
			return VolumeInitializationProof{}, err
		}
		if !mountOnly {
			return VolumeInitializationProof{}, fmt.Errorf("%w: volume has another attachment history", ErrForeignResource)
		}
		return VolumeInitializationProof{BootDescriptorSHA256: selected.BootDescriptorSHA256}, nil
	}
	operations, err := f.journal.ListOperations(ctx)
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	creates, attaches, otherAttachmentEffects := 0, 0, 0
	for _, operation := range operations {
		intent, result := operation.Intent, operation.Result
		if intent.Region != f.config.Region || intent.Generation != f.config.Generation || intent.Owner != f.config.Owner ||
			intent.VolumeID != pins.VolumeID && result.ResourceID != pins.VolumeID {
			continue
		}
		switch intent.Action {
		case actionVolumeCreate:
			if result.ResourceID == pins.VolumeID && !result.Unknown && !result.RecordedAt.IsZero() {
				creates++
			}
		case actionVolumeAttach:
			if intent.ResourceID == pins.InstanceID && intent.VolumeID == pins.VolumeID && intent.Device == pins.Device &&
				result.ResourceID == pins.AttachmentID && result.ETag == pins.AttachmentETag &&
				!result.Unknown && !result.RecordedAt.IsZero() {
				attaches++
			} else {
				otherAttachmentEffects++
			}
		case actionVolumeDetach:
			otherAttachmentEffects++
		}
	}
	proof := VolumeInitializationProof{BootDescriptorSHA256: selected.BootDescriptorSHA256}
	// The pin validation above admits only ext4 and xfs, both of which the
	// host initializer can format.
	if creates != 1 || attaches != 1 || otherAttachmentEffects != 0 {
		return proof, nil
	}
	if err := f.guard(ctx, epoch); err != nil {
		return VolumeInitializationProof{}, err
	}
	store, ok := f.journal.(VolumeFormatPermitStore)
	if !ok {
		return VolumeInitializationProof{}, errors.New("OCI journal cannot atomically consume volume format authority")
	}
	proof.AllowFormat, err = store.ClaimVolumeFormatPermit(ctx, VolumeFormatPermitRecord{
		Region: f.config.Region, Generation: f.config.Generation, Owner: f.config.Owner,
		DatabaseID: pins.DatabaseID, PartitionID: pins.PartitionID,
		InstanceID: pins.InstanceID, HostCreateKey: pins.HostCreateKey,
		VolumeID: pins.VolumeID, AttachmentID: pins.AttachmentID,
		AttachmentETag: pins.AttachmentETag, Device: pins.Device,
		FileSystemUUID: pins.FileSystemUUID, FileSystemType: pins.FileSystemType,
		BootDescriptorSHA256: selected.BootDescriptorSHA256,
	})
	if err != nil {
		return VolumeInitializationProof{}, err
	}
	return proof, nil
}

// mountExistingPermitted reports a reattached volume whose only live
// attachment is the pinned one and whose pinned attachment holds a recorded
// mount-existing permit for exactly this workload and instance.
func (f *fleet) mountExistingPermitted(ctx context.Context, pins VolumeInitializationPins, attachments []CloudAttachment) (bool, error) {
	live := liveAttachments(attachments)
	if len(live) != 1 || live[0].ID != pins.AttachmentID || live[0].InstanceID != pins.InstanceID {
		return false, nil
	}
	permit, found, err := f.mountPermit(ctx, pins.VolumeID, pins.AttachmentID)
	if err != nil {
		return false, fmt.Errorf("read volume mount permit: %w", err)
	}
	return found && permit.DatabaseID == pins.DatabaseID && permit.PartitionID == pins.PartitionID &&
		permit.ReplacementInstanceID == pins.InstanceID, nil
}

func (journal *KVJournal) ClaimVolumeFormatPermit(ctx context.Context, record VolumeFormatPermitRecord) (bool, error) {
	if journal == nil || record.Region == "" || record.Generation == 0 || record.Owner == "" ||
		!entityid.Valid(record.DatabaseID) || !entityid.Valid(record.PartitionID) || record.InstanceID == "" ||
		!entityid.Valid(record.HostCreateKey) || record.VolumeID == "" || record.AttachmentID == "" ||
		record.AttachmentETag == "" || !validDevicePath(record.Device) ||
		record.FileSystemUUID == "" || record.FileSystemType != "ext4" && record.FileSystemType != "xfs" ||
		!isLowerHexSHA256(record.BootDescriptorSHA256) {
		return false, errors.New("volume format permit record is incomplete")
	}
	data, err := json.Marshal(journalEntry{SchemaVersion: journalSchema, Kind: "format-permit", FormatPermit: record})
	if err != nil {
		return false, err
	}
	key := entityid.Derive("volume-format-permit", string(record.Region), fmt.Sprint(record.Generation), record.Owner, record.VolumeID)
	if _, err := journal.kv.Create(ctx, key, data); err == nil {
		return true, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		// A timed-out create might have committed. Never grant true without a
		// positive Create result, even if readback finds our exact bytes.
		return false, fmt.Errorf("create volume format permit: %w", err)
	}
	entry, err := journal.kv.Get(ctx, key)
	if err != nil {
		return false, err
	}
	var current journalEntry
	if err := json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)); err != nil {
		return false, err
	}
	if current.SchemaVersion != journalSchema || current.Kind != "format-permit" || current.FormatPermit != record {
		return false, errors.New("volume format permit key belongs to a different immutable binding")
	}
	return false, nil
}

func volumeMountPermitKey(region Region, generation uint64, owner, volumeID, attachmentID string) string {
	return entityid.Derive("volume-mount-permit", string(region), fmt.Sprint(generation), owner, volumeID, attachmentID)
}

func validVolumeMountPermitRecord(record VolumeMountPermitRecord) bool {
	return record.Region != "" && record.Generation != 0 && record.Owner != "" &&
		entityid.Valid(record.DatabaseID) && entityid.Valid(record.PartitionID) && record.VolumeID != "" &&
		record.AttachmentID != "" && record.ReplacementInstanceID != "" && record.FencedInstanceID != "" &&
		record.ReplacementInstanceID != record.FencedInstanceID && record.FencedInstanceState == instanceStateTerminated
}

// RecordVolumeMountPermit creates the immutable mount-existing permit of one
// replacement attachment. A retry with the exact record succeeds; any other
// record under the same key is refused.
func (journal *KVJournal) RecordVolumeMountPermit(ctx context.Context, record VolumeMountPermitRecord) error {
	if journal == nil || !validVolumeMountPermitRecord(record) {
		return errors.New("volume mount permit record is incomplete")
	}
	data, err := json.Marshal(journalEntry{SchemaVersion: journalSchema, Kind: "mount-permit", MountPermit: record})
	if err != nil {
		return err
	}
	key := volumeMountPermitKey(record.Region, record.Generation, record.Owner, record.VolumeID, record.AttachmentID)
	if _, err := journal.kv.Create(ctx, key, data); err == nil {
		return nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("create volume mount permit: %w", err)
	}
	current, found, err := journal.GetVolumeMountPermit(ctx, record.Region, record.Generation, record.Owner,
		record.VolumeID, record.AttachmentID)
	if err != nil {
		return err
	}
	if !found || current != record {
		return errors.New("volume mount permit key belongs to a different immutable binding")
	}
	return nil
}

// GetVolumeMountPermit reads the mount-existing permit of one attachment.
func (journal *KVJournal) GetVolumeMountPermit(ctx context.Context, region Region, generation uint64,
	owner, volumeID, attachmentID string,
) (VolumeMountPermitRecord, bool, error) {
	if journal == nil || region == "" || generation == 0 || owner == "" || volumeID == "" || attachmentID == "" {
		return VolumeMountPermitRecord{}, false, errors.New("volume mount permit lookup is incomplete")
	}
	entry, err := journal.kv.Get(ctx, volumeMountPermitKey(region, generation, owner, volumeID, attachmentID))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return VolumeMountPermitRecord{}, false, nil
	}
	if err != nil {
		return VolumeMountPermitRecord{}, false, err
	}
	var current journalEntry
	if err := json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)); err != nil {
		return VolumeMountPermitRecord{}, false, err
	}
	record := current.MountPermit
	if current.SchemaVersion != journalSchema || current.Kind != "mount-permit" || !validVolumeMountPermitRecord(record) || record.Region != region ||
		record.Generation != generation || record.Owner != owner || record.VolumeID != volumeID ||
		record.AttachmentID != attachmentID {
		return VolumeMountPermitRecord{}, false, errors.New("volume mount permit record is corrupt")
	}
	return record, true, nil
}

func validDevicePath(value string) bool {
	return len(value) > len("/dev/") && len(value) <= 255 && strings.HasPrefix(value, "/dev/") &&
		path.Clean(value) == value && strings.TrimSpace(value) == value &&
		!strings.ContainsAny(value, " \t\r\n\x00")
}

